import React from "react";
import { render, screen } from "@testing-library/react";
import App from "../App";

test("初始状态输入框为空且字符数为 0", () => {
  render(<App />);
  const input = screen.getByTestId("text-input");
  expect(input.value).toBe("");
  const count = screen.getByTestId("char-count");
  expect(count.textContent.trim()).toBe("0");
});

import React from "react";
import { render, screen, fireEvent } from "@testing-library/react";
import App from "../App";

test("输入 hello world 显示 11，改为 a b 显示 3，清空后回到 0", () => {
  render(<App />);
  const input = screen.getByTestId("text-input");
  const count = screen.getByTestId("char-count");

  fireEvent.change(input, { target: { value: "hello world" } });
  expect(input.value).toBe("hello world");
  expect(count.textContent.trim()).toBe("11");

  fireEvent.change(input, { target: { value: "a b" } });
  expect(count.textContent.trim()).toBe("3");

  fireEvent.change(input, { target: { value: "" } });
  expect(count.textContent.trim()).toBe("0");
});

import { countCharacters } from "../charCount";

test("countCharacters 统计字符数并计入空格", () => {
  expect(countCharacters("")).toBe(0);
  expect(countCharacters("hello world")).toBe(11);
  expect(countCharacters("a b")).toBe(3);
  expect(countCharacters("  ")).toBe(2);
});

