import React from "react";
import { render, screen, fireEvent } from "@testing-library/react";
import App from "../App";

test("输入 hello world 后点击清空按钮，输入框变空且字符数显示 0", () => {
  render(<App />);
  const input = screen.getByTestId("text-input");
  const count = screen.getByTestId("char-count");
  const clearButton = screen.getByTestId("clear-button");

  fireEvent.change(input, { target: { value: "hello world" } });
  expect(input.value).toBe("hello world");
  expect(count.textContent.trim()).toBe("11");

  fireEvent.click(clearButton);

  expect(input.value).toBe("");
  expect(count.textContent.trim()).toBe("0");
});

import React from "react";
import { render, screen, fireEvent } from "@testing-library/react";
import App from "../App";

test("输入 abc 后点击清空，再输入 xy z 字符数显示 4", () => {
  render(<App />);
  const input = screen.getByTestId("text-input");
  const count = screen.getByTestId("char-count");
  const clearButton = screen.getByTestId("clear-button");

  fireEvent.change(input, { target: { value: "abc" } });
  expect(count.textContent.trim()).toBe("3");

  fireEvent.click(clearButton);
  expect(input.value).toBe("");
  expect(count.textContent.trim()).toBe("0");

  fireEvent.change(input, { target: { value: "xy z" } });
  expect(input.value).toBe("xy z");
  expect(count.textContent.trim()).toBe("4");
});

